struct ProjectionLoanContext<'a,'b>{source:projection_clone::RetainedCloneRef<'a,ProjectionLoanProbe>,turn:&'a OriginalSourceTurn,op:ProjectionLoanOp,original:Option<&'a mut OriginalRetirementCloseLoan<'b>>}
