 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match c.op{ProjectionLoanOp::Advance=>self.field.advance_into(c.source,4096,4096,effect,reply),ProjectionLoanOp::Original=>{self.control_receives+=1;let done=self.field.advance_original_into(c.original.as_deref_mut().ok_or_else(||ValueError::invariant("original loan absent"))?,effect,reply)?;if self.interrupt_control{self.interrupt_control=false;panic!("original control reply recorded before unwind")}Ok(done)},ProjectionLoanOp::Start=>self.field.begin_close_into(effect,reply),ProjectionLoanOp::Close=>self.field.close_into(effect,reply)}}
