#[test]fn projection_advance_uses_same_source_bound_decoder_birth_loan(){let law:serde_json::Value=serde_json::from_str(include_str!("projection-loan.json")).unwrap();let mut bank=projection_source_bank::Bank::from_stock(&law["stock"],false);let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut source=projection_clone::RetainedCloneSource::<ProjectionLoanProbe>::from_owner(ProjectionLoanProbe{ledger:native.ledger_identity(),recipient:native.retirement_recipient_identity()});let reference=source.borrow();let mut authority=OriginalEffectAuthority::new(ProjectionLoanProducer{field:std::mem::ManuallyDrop::new(Default::default()),source:reference.reference_identity(),turn:bank.turn.identity(),interrupt_control:true,control_receives:0,control_recovers:0});let mut frame=NativeReceivingEffect::default();
 for _ in 0..64{if authority.inspect(|p|p.field.requires_original_birth()){break}let(d,units)=authority.inspect(|p|(p.field.demands(reference,4096,4096).unwrap(),p.field.advance_work_demand(reference,4096,4096).unwrap()));let poll=bank.run_with_turn(&mut native,|turn,control|control.receive_original_effect(d,units,&mut frame,&mut authority,|_,effect,authority,action|{let mut context=ProjectionLoanContext{source:reference,turn,op:ProjectionLoanOp::Advance,original:None};authority.drive(&mut context,effect,action)})).unwrap();match poll{NativeReceivingEffectPoll::Complete(turn)=>{turn.result.unwrap();},_=>panic!("projection advance unexpectedly pending")}}assert!(authority.inspect(|p|p.field.requires_original_birth()));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:law["birth"]["copyBytes"].as_u64().unwrap() as usize,maximum_depth:1,..Default::default()};let poll=bank.run_with_turn(&mut native,|turn,control|control.with_retirement(grant,|funding|funding.with_original_close(|original|{let mut context=ProjectionLoanContext{source:reference,turn,op:ProjectionLoanOp::Advance,original:None};authority.drive_original_birth(&mut context,original,grant)}))).unwrap();let RetainedWorkPoll::Complete(done)=poll else{panic!("projection Birth stayed pending")};assert_eq!(done.work,u128::from(law["birth"]["work"].as_u64().unwrap()));assert_eq!(done.result.unwrap().progress().copied_bytes,grant.maximum_copy_bytes);assert!(!authority.inspect(|p|p.field.requires_original_birth()));assert!(authority.inspect(|p|p.field.requires_original_control()));let(d,units)=authority.inspect(|p|(p.field.demands(reference,4096,4096).unwrap(),p.field.advance_work_demand(reference,4096,4096).unwrap()));let control_grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let mut drive=||bank.run_with_turn(&mut native,|turn,control|control.receive_original_effect(d,units,&mut frame,&mut authority,|native,effect,authority,action|native.with_retirement(control_grant,|funding|funding.with_original_close(|original|{let mut context=ProjectionLoanContext{source:reference,turn,op:ProjectionLoanOp::Original,original:Some(original)};authority.drive(&mut context,effect,action)}))));let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(&mut drive));assert!(interrupted.is_err());let poll=drive().unwrap();drop(drive);assert_eq!(authority.inspect(|p|p.control_receives),1);assert_eq!(authority.inspect(|p|p.control_recovers),law["control"]["recoveries"].as_u64().unwrap() as usize);let NativeReceivingEffectPoll::Complete(done)=poll else{panic!("projection original control stayed pending")};assert_eq!(done.work,u128::from(law["control"]["work"].as_u64().unwrap()));assert_eq!(done.result.unwrap().progress().copied_bytes,law["control"]["copyBytes"].as_u64().unwrap() as usize);assert!(!authority.inspect(|p|p.field.requires_original_control()));
 for op in [ProjectionLoanOp::Start,ProjectionLoanOp::Close]{for _ in 0..128{if matches!(op,ProjectionLoanOp::Start)&&authority.inspect(|p|p.field.close_started())||matches!(op,ProjectionLoanOp::Close)&&authority.inspect(|p|p.field.terminal_is_empty()){break}let(d,units)=authority.inspect(|p|match op{ProjectionLoanOp::Start=>(p.field.begin_close_demand().unwrap(),p.field.begin_close_work_demand().unwrap()),ProjectionLoanOp::Close=>(p.field.close_demands(4096).unwrap(),p.field.close_work_demand(4096).unwrap()),_=>unreachable!()});let poll=bank.run_with_turn(&mut native,|turn,control|control.receive_original_effect(d,units,&mut frame,&mut authority,|_,effect,authority,action|{let mut context=ProjectionLoanContext{source:reference,turn,op,original:None};authority.drive(&mut context,effect,action)})).unwrap();match poll{NativeReceivingEffectPoll::Complete(turn)=>{turn.result.unwrap();},_=>panic!("projection cleanup unexpectedly pending")}}}assert!(authority.inspect(|p|p.field.terminal_is_empty()));drop(authority.into_producer().ok().unwrap());for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("projection input Source refused cleanup"),_=>{}}}assert!(source.terminal_is_empty());}
